"""Pure authoring contract checks; no engine account, storage or network access."""
import hashlib,json,pathlib,subprocess,sys
repo=pathlib.Path(sys.argv[1]);dotnet=sys.argv[2];dll=repo/'targets/element-authoring/bin/Release/net10.0/Confectory.ElementAuthoring.dll'
def unit(name,kind,text):return {'id':'Owned.Folders::'+name,'kind':kind,'text':text,'revision':0,'hash':hashlib.sha256(text.encode()).hexdigest()}
rows=[unit('Unit','object','object Owned.Folders::Unit { value keep = "한글"; }'),unit('Other','object','object Owned.Folders::Other extends Owned.Folders::Unit {description "source";}'),unit('Third','object','object Owned.Folders::Third extends Owned.Folders::Unit {}'),unit('A','category','category Owned.Folders::A {contain object Owned.Folders::Other;}'),unit('B','category','category Owned.Folders::B {}'),unit('Features','category','category Owned.Folders::Features {value editorBrowserGroup = "feature";}')]
def move(name,target):
 source=next(r for r in rows if r['id'].endswith('::'+name));folder=next((r for r in rows if r['id'].endswith('::'+str(target))),None)
 return {'id':source['id'],'revision':source['revision'],'hash':source['hash'],'folder':folder['id'] if folder else None,'folderRevision':folder['revision'] if folder else None,'folderHash':folder['hash'] if folder else None}
def call(moves,success=True,values=None):
 request={'operation':'browserFolderMove','namespace':'Owned.Folders','units':values or rows,'moves':moves};r=subprocess.run([dotnet,str(dll)],input=json.dumps(request),capture_output=True,text=True);reply=json.loads(r.stdout);assert reply.get('ok')==success,(r.stdout,r.stderr);return reply['result'] if success else reply
v=call([move('Other','A')]);assert len(v['changes'])==1;assert 'extends Owned.Folders::Unit' in v['changes'][0]['text'];assert 'description "source"' in v['changes'][0]['text'];assert 'editorFolder' in v['changes'][0]['text'];assert set(v['group'])=={'Owned.Folders::Other','Owned.Folders::A'};assert rows[3]['text']=='category Owned.Folders::A {contain object Owned.Folders::Other;}';print('PASS category classification retains inheritance, IDs, namespace, typed contain source and source description; declares exact dependency group')
v=call([move('Other','A'),move('Third','B')]);assert len(v['changes'])==2;assert set(v['moved'])=={'Owned.Folders::Other','Owned.Folders::Third'};print('PASS multiple classification replacements are prepared together with both category proofs')
stale=move('Other','A');stale['folderRevision']=1;call([stale],False);stale=move('Other','A');stale['hash']='0'*64;call([stale],False);call([move('Other','Features')],False);foreign=move('Other','A');foreign['folder']='Foreign::Category';call([foreign],False);print('PASS stale source/category proof, foreign category and cross-tab classification fail closed')
cycle=json.loads(json.dumps(rows));cycle[4]['text']='category Owned.Folders::B {value editorFolder = "Owned.Folders::A";}';cycle[4]['hash']=hashlib.sha256(cycle[4]['text'].encode()).hexdigest();cyclic=move('A','B');cyclic['folderHash']=cycle[4]['hash'];call([cyclic],False,cycle);print('PASS a category cannot move below its descendant; no replacement set is returned')

combined=json.loads(json.dumps(rows));combined[4]['text']='category Owned.Folders::B extends Owned.Folders::A {}';combined[4]['hash']=hashlib.sha256(combined[4]['text'].encode()).hexdigest();mixed=move('A','B');mixed['folderHash']=combined[4]['hash'];call([mixed],False,combined);print('PASS combined inherited/category display cycles are rejected while keeping source inheritance unchanged')
